#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define N 10
static int parent[N];
static int rank_arr[N];

static int find_set(int v) {
    if (parent[v] != v)
        parent[v] = find_set(parent[v]);
    return parent[v];
}

static void union_sets(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) {
        if (rank_arr[a] < rank_arr[b])
            parent[a] = b;
        else if (rank_arr[a] > rank_arr[b])
            parent[b] = a;
        else {
            parent[b] = a;
            rank_arr[a]++;
        }
    }
}

int main(int argc, char **argv) {
    // initialise union‑find for elements 0..9
    for (int i = 0; i < N; ++i) {
        parent[i] = i;
        rank_arr[i] = 0;
    }

    // process commands starting after program name (argv[0])
    for (int i = 1; i < argc; ) {
        char *cmd = argv[i];
        if (cmd == NULL) { break; }
        if (strcmp(cmd, "U") == 0) {               // UNION command
            if (i + 2 < argc) {
                int a = (int)strtol(argv[i+1], NULL, 10);
                int b = (int)strtol(argv[i+2], NULL, 10);
                if (0 <= a && a < N && 0 <= b && b < N) {
                    union_sets(a, b);
                    printf("UNION %d %d\n", a, b);
                    i += 3;
                    continue;
                }
            }
            puts("INVALID");
            i += 1; // skip only the command token
        } else if (strcmp(cmd, "F") == 0) {        // FIND command
            if (i + 1 < argc) {
                int a = (int)strtol(argv[i+1], NULL, 10);
                if (0 <= a && a < N) {
                    int root = find_set(a);
                    printf("FIND %d=%d\n", a, root);
                    i += 2;
                    continue;
                }
            }
            puts("INVALID");
            i += 1;
        } else if (strcmp(cmd, "C") == 0) {        // CONNECTED query
            if (i + 2 < argc) {
                int a = (int)strtol(argv[i+1], NULL, 10);
                int b = (int)strtol(argv[i+2], NULL, 10);
                if (0 <= a && a < N && 0 <= b && b < N) {
                    int ra = find_set(a);
                    int rb = find_set(b);
                    puts(ra == rb ? "YES" : "NO");
                    i += 3;
                    continue;
                }
            }
            puts("INVALID");
            i += 1;
        } else {
            puts("NOOP");
            i += 1;
        }
    }
    return 0;
}
